const body = $json.body || $json;
const type = body.type;
const payload = body.payload || {};

const color = '#7c2d12';

function btn(url, label) {
  return '<p style="margin:24px 0;"><a href="' + url + '" style="display:inline-block;padding:12px 20px;background:' + color + ';color:#fff;text-decoration:none;border-radius:8px;font-weight:600;">' + label + '</a></p>';
}

function wrap(title, content) {
  return '<div style="font-family:Arial,sans-serif;max-width:640px;margin:0 auto;color:#1f2937;line-height:1.6;"><h2 style="color:' + color + ';margin-bottom:16px;">' + title + '</h2>' + content + '<p style="margin-top:32px;color:#6b7280;font-size:13px;border-top:1px solid #e5e7eb;padding-top:16px;">Nariño Cultura &mdash; Plataforma cultural de la región Nariño, Colombia</p></div>';
}

function fmtDate(iso) {
  if (!iso) return '';
  try { return new Date(iso).toLocaleString('es-CO', {timeZone:'America/Bogota', dateStyle:'long', timeStyle:'short'}); }
  catch(e) { return iso; }
}

function fmtPrice(val) {
  if (!val) return '';
  return '$' + Number(val).toLocaleString('es-CO') + ' COP';
}

// AUCTION_OPENED: artista recibe correo de aprobacion
if (type === 'AUCTION_OPENED') {
  const name = payload.seller_name || 'artista';
  const title = payload.artwork_title || 'tu obra';
  const ends = fmtDate(payload.ends_at);
  return [{ json: {
    to: payload.seller_email || '',
    subject: '¡Tu subasta fue aprobada! — ' + title,
    html: wrap('¡Subasta aprobada!',
      '<p>Hola ' + name + ',</p>' +
      '<p>Tu solicitud de subasta para <strong>' + title + '</strong> fue aprobada y ya está activa en la plataforma.</p>' +
      (ends ? '<p>La subasta cierra el: <strong>' + ends + '</strong></p>' : '') +
      '<p>Los compradores ya pueden ver y pujar por tu obra. ¡Mucho éxito!</p>'
    )
  }}];
}

// AUCTION_REJECTED: artista recibe correo de rechazo
if (type === 'AUCTION_REJECTED') {
  const name = payload.seller_name || 'artista';
  const title = payload.artwork_title || 'tu obra';
  return [{ json: {
    to: payload.seller_email || '',
    subject: 'Subasta no aprobada — ' + title,
    html: wrap('Subasta no aprobada',
      '<p>Hola ' + name + ',</p>' +
      '<p>La solicitud de subasta para <strong>' + title + '</strong> no fue aprobada en esta ocasión.</p>' +
      '<p>Si tienes preguntas sobre los motivos, puedes contactar al equipo de Nariño Cultura respondiendo este correo.</p>'
    )
  }}];
}

// AUCTION_CLOSED con ganador: ganador recibe correo de felicitacion
if (type === 'AUCTION_CLOSED' && payload.winner_email) {
  const name = payload.winner_name || 'usuario';
  const title = payload.artwork_title || 'la obra';
  const price = fmtPrice(payload.final_price);
  return [{ json: {
    to: payload.winner_email,
    subject: '¡Ganaste la subasta! — ' + title,
    html: wrap('¡Felicitaciones, ganaste!',
      '<p>Hola ' + name + ',</p>' +
      '<p>¡Eres el ganador de la subasta de <strong>' + title + '</strong>!</p>' +
      (price ? '<p>Precio final: <strong>' + price + '</strong></p>' : '') +
      '<p>Nuestro equipo se comunicará contigo pronto para coordinar el pago y la entrega de la obra.</p>'
    )
  }}];
}

// EVENT_REGISTRATION: usuario recibe confirmacion de inscripcion
if (type === 'EVENT_REGISTRATION') {
  const name = payload.user_name || 'usuario';
  const title = payload.event_title || 'el evento';
  const date = fmtDate(payload.event_date);
  const loc = payload.event_location || '';
  return [{ json: {
    to: payload.user_email || '',
    subject: 'Inscripción confirmada — ' + title,
    html: wrap('Inscripción confirmada',
      '<p>Hola ' + name + ',</p>' +
      '<p>Tu inscripción al evento <strong>' + title + '</strong> fue confirmada exitosamente.</p>' +
      (date ? '<p>Fecha: <strong>' + date + '</strong></p>' : '') +
      (loc ? '<p>Lugar: <strong>' + loc + '</strong></p>' : '') +
      '<p>¡Te esperamos!</p>'
    )
  }}];
}

// Tipos sin email: AUCTION_PENDING, AUCTION_BID, ORDER_CREATED, PAYMENT_*, EVENT_PUBLISHED
return [{ json: { to: '', subject: '', html: '' } }];
